def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_values = [r[i] for r in rows if i < len(r)]
        numeric_values = [v for v in col_values if isinstance(v, (int, float))]
        if numeric_values:
            totals.append(sum(numeric_values))
        else:
            totals.append("")
    return totals

def render_rows(rows, mark_last=False):
    if mark_last and rows:
        normal_rows = rows[:-1]
        last_row = rows[-1]
        rendered_normal = [",".join(str(v) for v in r) for r in normal_rows]
        rendered_last = "TOTAL," + ",".join(str(v) for v in last_row)
        return rendered_normal + [rendered_last]
    else:
        return [",".join(str(v) for v in r) for r in rows]

